import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 7.8
.target sm_89
.address_size 64

// Convolution: NCHW input (N,3,224,224), weight (96,3,11,11), bias (96),
// stride 4, padding 2, output (N,96,55,55). One thread per output element.
.visible .entry conv2d_kernel(
    .param .u64 param_in,
    .param .u64 param_w,
    .param .u64 param_b,
    .param .u64 param_out,
    .param .u32 param_total
)
{
    .reg .b64 %rd_in, %rd_w, %rd_b, %rd_out, %rd_addr;
    .reg .b32 %r_tid, %r_idx, %r_total;
    .reg .b32 %r_n, %r_k, %r_oh, %r_ow, %r_t0, %r_t1;
    .reg .b32 %r_c, %r_kh, %r_kw, %r_ih, %r_iw;
    .reg .b32 %r_in_off, %r_w_off, %r_in_base;
    .reg .f32 %f_acc, %f_v, %f_w, %f_b;
    .reg .pred %p, %p1, %p2;

    ld.param.u64 %rd_in, [param_in];
    ld.param.u64 %rd_w, [param_w];
    ld.param.u64 %rd_b, [param_b];
    ld.param.u64 %rd_out, [param_out];
    ld.param.u32 %r_total, [param_total];

    mov.u32 %r_tid, %tid.x;
    mov.u32 %r_t0, %ctaid.x;
    mov.u32 %r_t1, %ntid.x;
    mad.lo.u32 %r_idx, %r_t0, %r_t1, %r_tid;

    setp.ge.u32 %p, %r_idx, %r_total;
    @%p bra DONE;

    // Decompose linear index into (n, k, oh, ow) with outH = outW = 55, K = 96.
    rem.u32 %r_ow, %r_idx, 55;
    div.u32 %r_t0, %r_idx, 55;
    rem.u32 %r_oh, %r_t0, 55;
    div.u32 %r_t0, %r_t0, 55;
    rem.u32 %r_k, %r_t0, 96;
    div.u32 %r_n, %r_t0, 96;

    mov.f32 %f_acc, 0f00000000;

    // Per-image input base: n * 3 * 224 * 224 = n * 150528.
    mul.lo.u32 %r_in_base, %r_n, 150528;

    mov.u32 %r_c, 0;
LOOP_C:
    mov.u32 %r_kh, 0;
LOOP_KH:
    // ih = oh*4 + kh - 2 (unsigned wrap marks negative values)
    mul.lo.u32 %r_t0, %r_oh, 4;
    add.u32 %r_t0, %r_t0, %r_kh;
    sub.u32 %r_ih, %r_t0, 2;
    setp.ge.u32 %p1, %r_ih, 224;

    mov.u32 %r_kw, 0;
LOOP_KW:
    // iw = ow*4 + kw - 2
    mul.lo.u32 %r_t0, %r_ow, 4;
    add.u32 %r_t0, %r_t0, %r_kw;
    sub.u32 %r_iw, %r_t0, 2;
    setp.ge.u32 %p2, %r_iw, 224;

    or.pred %p, %p1, %p2;
    @%p bra SKIP;

    // input offset = in_base + c*50176 + ih*224 + iw
    mul.lo.u32 %r_t0, %r_c, 50176;
    add.u32 %r_t0, %r_t0, %r_in_base;
    mul.lo.u32 %r_t1, %r_ih, 224;
    add.u32 %r_t0, %r_t0, %r_t1;
    add.u32 %r_in_off, %r_t0, %r_iw;

    mul.wide.u32 %rd_addr, %r_in_off, 4;
    add.u64 %rd_addr, %rd_addr, %rd_in;
    ld.global.f32 %f_v, [%rd_addr];

    // weight offset = ((k*3 + c)*11 + kh)*11 + kw
    mul.lo.u32 %r_t0, %r_k, 3;
    add.u32 %r_t0, %r_t0, %r_c;
    mul.lo.u32 %r_t0, %r_t0, 11;
    add.u32 %r_t0, %r_t0, %r_kh;
    mul.lo.u32 %r_t0, %r_t0, 11;
    add.u32 %r_w_off, %r_t0, %r_kw;

    mul.wide.u32 %rd_addr, %r_w_off, 4;
    add.u64 %rd_addr, %rd_addr, %rd_w;
    ld.global.f32 %f_w, [%rd_addr];

    fma.rn.f32 %f_acc, %f_v, %f_w, %f_acc;

SKIP:
    add.u32 %r_kw, %r_kw, 1;
    setp.lt.u32 %p, %r_kw, 11;
    @%p bra LOOP_KW;

    add.u32 %r_kh, %r_kh, 1;
    setp.lt.u32 %p, %r_kh, 11;
    @%p bra LOOP_KH;

    add.u32 %r_c, %r_c, 1;
    setp.lt.u32 %p, %r_c, 3;
    @%p bra LOOP_C;

    // Add bias.
    mul.wide.u32 %rd_addr, %r_k, 4;
    add.u64 %rd_addr, %rd_addr, %rd_b;
    ld.global.f32 %f_b, [%rd_addr];
    add.f32 %f_acc, %f_acc, %f_b;

    // Store result.
    mul.wide.u32 %rd_addr, %r_idx, 4;
    add.u64 %rd_addr, %rd_addr, %rd_out;
    st.global.f32 [%rd_addr], %f_acc;

DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("conv2d_kernel")

class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super().__init__()
        # Match the reference constructor and parameters exactly.
        self.conv1 = nn.Conv2d(in_channels=3, out_channels=96, kernel_size=11, stride=4, padding=2)

    def forward(self, x):
        batch_size = x.shape[0]
        out_h = (x.shape[2] + 2 * 2 - 11) // 4 + 1
        out_w = (x.shape[3] + 2 * 2 - 11) // 4 + 1
        out = torch.empty((batch_size, 96, out_h, out_w), dtype=x.dtype, device=x.device)
        total = out.numel()
        block_x = 256
        grid_x = (total + block_x - 1) // block_x
        module = _get_ptx_module()
        module.launch(
            "conv2d_kernel",
            grid=(grid_x, 1, 1),
            block=(block_x, 1, 1),
            arguments=[x, self.conv1.weight, self.conv1.bias, out, u32(total)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return out

